    _em("scan: the stray GAP is told every time", "		if (x->sc_stray == 1u || (x->sc_stray & 63u) == 0u) {", "		if (1) {"),
    _em("scan: the stray GAP is not counted in gaps=N", "			swl_gap(\"scan\", \"ESCAN_RESULT outside a keep-phase scan ignored\", \"low\");\n", ""),
    _em("scan: an event shorter than its header is read", "	if (ev->edlen < 12u) {\n		x->sc_other++;", "	if (0) {\n		x->sc_other++;"),
